"""Helper script to generate ready-to-use .env files for local dev, CRM, and Evolution API.

Usage:
    python scripts/generate_envs.py
    python scripts/generate_envs.py --crm-domain crm.example.com --evolution-domain evo.example.com
"""

import argparse
import secrets
from pathlib import Path


def build_local_dev_env(secret_key: str) -> str:
    """Build a safe local development .env (never sends external WhatsApp/emails)."""
    return f"""# ==============================================================================
# CarteFidele Scraper & CRM - Local Development (.env)
# Generated by scripts/generate_envs.py
# ==============================================================================

APP_ENV=development
ALLOW_EXTERNAL_MESSAGING=false

# --- Authentication & Security ---
APP_USERNAME=admin
APP_PASSWORD=ChangeThisLocalPassword!
SECRET_KEY={secret_key}
SESSION_MAX_AGE=604800

# --- Server ---
PORT=8000
HOST=0.0.0.0
HEADLESS=true
CONCURRENCY_LIMIT=1

# --- Email (Resend - simulated in development) ---
RESEND_API_KEY=
RESEND_FROM_EMAIL=hello@outreach.cartefidele.com
RESEND_REPLY_TO=contact@cartefidele.com
RESEND_WEBHOOK_SECRET=

# --- WhatsApp (Enforced Mock in development) ---
WHATSAPP_ENABLED=false
WHATSAPP_PROVIDER=mock
EVOLUTION_API_ENABLED=false
EVOLUTION_API_BASE_URL=
EVOLUTION_API_KEY=
EVOLUTION_API_INSTANCE=
EVOLUTION_WEBHOOK_SECRET=
"""


def build_crm_prod_env(
    *,
    secret_key: str,
    evolution_domain: str,
    evolution_api_key: str,
    evolution_instance: str,
    evolution_webhook_secret: str,
) -> str:
    """Build production Railway environment variables for the CarteFidele CRM service."""
    evo_url = (
        evolution_domain
        if evolution_domain.startswith("http")
        else f"https://{evolution_domain}"
    )
    return f"""# ==============================================================================
# CarteFidele Scraper & CRM - Production Railway Environment
# Paste these into your CRM Railway Service -> Variables
# ==============================================================================

APP_ENV=production
ALLOW_EXTERNAL_MESSAGING=true

# --- Authentication & Security ---
APP_USERNAME=admin
APP_PASSWORD=REPLACE_WITH_STRONG_ADMIN_PASSWORD
SECRET_KEY={secret_key}
SESSION_MAX_AGE=604800
RATE_LIMIT_ENABLED=true
RATE_LIMIT_MAX_REQUESTS=60
RATE_LIMIT_WINDOW_SECONDS=60

# --- Server & Persistent Storage (Mount Railway Volume at /app/output) ---
PORT=8000
HOST=0.0.0.0
OUTPUT_DIR=/app/output
HEADLESS=true
CONCURRENCY_LIMIT=1

# --- Email Outreach (Resend) ---
RESEND_API_KEY=REPLACE_WITH_RESEND_API_KEY
RESEND_FROM_EMAIL=CarteFidele <hello@outreach.cartefidele.com>
RESEND_REPLY_TO=contact@cartefidele.com
RESEND_WEBHOOK_SECRET=

# --- WhatsApp Outreach (Self-Hosted Evolution API on Railway) ---
WHATSAPP_ENABLED=true
WHATSAPP_PROVIDER=evolution
EVOLUTION_API_ENABLED=true
EVOLUTION_API_BASE_URL={evo_url}
EVOLUTION_API_KEY={evolution_api_key}
EVOLUTION_API_INSTANCE={evolution_instance}
EVOLUTION_WEBHOOK_SECRET={evolution_webhook_secret}
"""


def build_evolution_railway_env(
    *,
    crm_domain: str,
    evolution_domain: str,
    evolution_api_key: str,
    use_redis: bool = True,
) -> str:
    """Build production Railway environment variables for evoapicloud/evolution-api:latest."""
    evo_url = (
        evolution_domain
        if evolution_domain.startswith("http")
        else f"https://{evolution_domain}"
    )
    crm_url = crm_domain if crm_domain.startswith("http") else f"https://{crm_domain}"

    return f"""# ==============================================================================
# Self-Hosted Evolution API (evoapicloud/evolution-api:latest) - Railway Env
# Paste these into your Evolution API Railway Service -> Variables
# ==============================================================================

SERVER_NAME=evolution
SERVER_TYPE=http
SERVER_PORT=8080
SERVER_URL={evo_url}
CORS_ORIGIN=*
CORS_METHODS=GET,POST,PUT,DELETE
CORS_CREDENTIALS=true

TELEMETRY_ENABLED=false
LOG_LEVEL=ERROR,WARN,INFO
LOG_COLOR=false
LOG_BAILEYS=error
EVENT_EMITTER_MAX_LISTENERS=50

AUTHENTICATION_API_KEY={evolution_api_key}
AUTHENTICATION_EXPOSE_IN_FETCH_INSTANCES=true
LANGUAGE=en

DEL_INSTANCE=false
CONFIG_SESSION_PHONE_CLIENT=CarteFidele
CONFIG_SESSION_PHONE_NAME=Chrome
QRCODE_LIMIT=30
QRCODE_COLOR='#175197'

# --- PostgreSQL (Attach Railway Postgres) ---
DATABASE_PROVIDER=postgresql
DATABASE_CONNECTION_URI=${{{{Postgres.DATABASE_URL}}}}?schema=evolution_api
DATABASE_CONNECTION_CLIENT_NAME=cartefidele_evolution
DATABASE_SAVE_DATA_INSTANCE=true
DATABASE_SAVE_DATA_NEW_MESSAGE=true
DATABASE_SAVE_MESSAGE_UPDATE=true
DATABASE_SAVE_DATA_CONTACTS=true
DATABASE_SAVE_DATA_CHATS=true
DATABASE_SAVE_DATA_LABELS=true
DATABASE_SAVE_DATA_HISTORIC=false
DATABASE_SAVE_IS_ON_WHATSAPP=true
DATABASE_SAVE_IS_ON_WHATSAPP_DAYS=7
DATABASE_DELETE_MESSAGE=true

# --- Redis Cache ---
CACHE_REDIS_ENABLED={'true' if use_redis else 'false'}
CACHE_REDIS_URI=${{{{Redis.REDIS_URL}}}}
CACHE_REDIS_TTL=604800
CACHE_REDIS_PREFIX_KEY=evolution
CACHE_REDIS_SAVE_INSTANCES={'true' if use_redis else 'false'}
CACHE_LOCAL_ENABLED={'false' if use_redis else 'true'}

# --- Global Webhook -> CarteFidele CRM ---
WEBHOOK_GLOBAL_ENABLED=true
WEBHOOK_GLOBAL_URL={crm_url}/api/webhooks/evolution
WEBHOOK_GLOBAL_WEBHOOK_BY_EVENTS=false
WEBHOOK_EVENTS_QRCODE_UPDATED=true
WEBHOOK_EVENTS_MESSAGES_UPSERT=true
WEBHOOK_EVENTS_MESSAGES_UPDATE=true
WEBHOOK_EVENTS_SEND_MESSAGE=true
WEBHOOK_EVENTS_CONNECTION_UPDATE=true
WEBHOOK_EVENTS_APPLICATION_STARTUP=false
WEBHOOK_EVENTS_MESSAGES_SET=false
WEBHOOK_EVENTS_CONTACTS_SET=false
WEBHOOK_EVENTS_CHATS_SET=false
WEBHOOK_REQUEST_TIMEOUT_MS=60000
WEBHOOK_RETRY_MAX_ATTEMPTS=10
WEBHOOK_RETRY_INITIAL_DELAY_SECONDS=5
WEBHOOK_RETRY_USE_EXPONENTIAL_BACKOFF=true
WEBHOOK_RETRY_MAX_DELAY_SECONDS=300
WEBHOOK_RETRY_JITTER_FACTOR=0.2
WEBHOOK_RETRY_NON_RETRYABLE_STATUS_CODES=400,401,403,404,422

# --- Disabled Optional Integrations ---
PROMETHEUS_METRICS=false
RABBITMQ_ENABLED=false
SQS_ENABLED=false
WEBSOCKET_ENABLED=false
PUSHER_ENABLED=false
KAFKA_ENABLED=false
TYPEBOT_ENABLED=false
CHATWOOT_ENABLED=false
OPENAI_ENABLED=false
DIFY_ENABLED=false
N8N_ENABLED=false
EVOAI_ENABLED=false
S3_ENABLED=false
"""


def generate_env_files(
    out_dir: Path,
    crm_domain: str = "YOUR-CRM-RAILWAY-DOMAIN",
    evolution_domain: str = "YOUR-EVOLUTION-RAILWAY-DOMAIN",
    instance: str = "cartefidele-main",
    use_redis: bool = True,
    force: bool = False,
) -> dict[str, Path]:
    """Generate local, CRM production, and Evolution API env files in out_dir."""
    out_dir.mkdir(parents=True, exist_ok=True)
    local_secret = secrets.token_hex(32)
    prod_secret = secrets.token_hex(32)
    evo_api_key = secrets.token_hex(24)
    evo_webhook_secret = secrets.token_urlsafe(24)

    files = {
        "local": (out_dir / ".env.local.ready", build_local_dev_env(local_secret)),
        "crm_prod": (
            out_dir / ".env.crm.production.ready",
            build_crm_prod_env(
                secret_key=prod_secret,
                evolution_domain=evolution_domain,
                evolution_api_key=evo_api_key,
                evolution_instance=instance,
                evolution_webhook_secret=evo_webhook_secret,
            ),
        ),
        "evolution_prod": (
            out_dir / ".env.evolution.railway.ready",
            build_evolution_railway_env(
                crm_domain=crm_domain,
                evolution_domain=evolution_domain,
                evolution_api_key=evo_api_key,
                use_redis=use_redis,
            ),
        ),
    }

    written: dict[str, Path] = {}
    for key, (path, content) in files.items():
        if path.exists() and not force:
            raise FileExistsError(f"{path} already exists. Pass --force to overwrite.")
        path.write_text(content, encoding="utf-8")
        written[key] = path
    return written


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate ready-to-use .env files for CarteFidele CRM and Evolution API."
    )
    parser.add_argument("--out-dir", type=Path, default=Path("."), help="Directory to write generated env files")
    parser.add_argument("--crm-domain", default="YOUR-CRM-RAILWAY-DOMAIN", help="Public Railway domain for CRM")
    parser.add_argument("--evolution-domain", default="YOUR-EVOLUTION-RAILWAY-DOMAIN", help="Public Railway domain for Evolution API")
    parser.add_argument("--instance", default="cartefidele-main", help="Evolution API WhatsApp instance name")
    parser.add_argument("--no-redis", action="store_true", help="Disable Redis cache in Evolution API env")
    parser.add_argument("--force", action="store_true", help="Overwrite existing generated env files")
    args = parser.parse_args()

    written = generate_env_files(
        out_dir=args.out_dir,
        crm_domain=args.crm_domain,
        evolution_domain=args.evolution_domain,
        instance=args.instance,
        use_redis=not args.no_redis,
        force=args.force,
    )
    for label, path in written.items():
        print(f"Generated {label}: {path}")
    print("\nNote: Keep .env.*.ready files private and never commit real secrets to Git.")


if __name__ == "__main__":
    main()
